// Generates web/css/packs.css and web/js/iconData.js from the ChatGPT design kit in design/momentum/ (single source of truth).
// Run: npm run design   (a unit test fails when the generated files are out of date).
import { readFileSync, writeFileSync } from 'node:fs';
const tokens = JSON.parse(readFileSync('design/momentum/tokens.json', 'utf8'));
const assets = JSON.parse(readFileSync('design/momentum/assets.json', 'utf8')).assets;
const DEFAULT = 'momentum';
const vars = (t) => Object.entries(t).map(([k, v]) => `--${k.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase())}:${v}`).join(';');
let css = '/* GENERATED by scripts/build-design.mjs from design/momentum/tokens.json - do not edit. */\n';
for (const [name, m] of Object.entries(tokens)) {
  const pack = name === DEFAULT ? ':not([data-pack])' : `[data-pack="${name}"]`;
  css += `:root${pack}{${vars(m.light)}}\n`;
  css += `@media (prefers-color-scheme:dark){:root${pack}:not([data-theme="light"]){${vars(m.dark)}}}\n`;
  css += `:root${pack}[data-theme="dark"]{${vars(m.dark)}}\n`;
}
writeFileSync('web/css/packs.css', css);
// Icons as data (tag + attributes), drawn with createElementNS: no innerHTML anywhere.
const icons = {};
for (const [key, svg] of Object.entries(assets)) {
  if (!key.startsWith('ui-')) continue;
  const kids = [...svg.matchAll(/<(circle|path|rect|line|polyline|polygon|ellipse)\b([^>]*?)\/>/g)].map(([, tag, attrs]) => [tag, Object.fromEntries([...attrs.matchAll(/([\w-]+)="([^"]*)"/g)].map((m) => [m[1], m[2]]))]);
  icons[key.slice(3)] = kids;
}
writeFileSync('web/js/iconData.js', `// GENERATED by scripts/build-design.mjs from design/momentum/assets.json - do not edit.\nexport const ICONS = ${JSON.stringify(icons)};\n`);
console.log(`design ok (${Object.keys(tokens).length} packs, ${Object.keys(icons).length} icons)`);
